define(['jquery', 'Magento_Ui/js/modal/modal', 'Magento_Customer/js/customer-data', 'mage/url', 'slick'], function($, modal, customerData, urlBuilder) {
    return function(config) {
        $(document).ready(function() {
            var ajaxsuites_url = urlBuilder.build("ajaxsuites/Wishlist/add");
            var redirect_url = urlBuilder.build("customer/account/login");
            var options = {
                type: 'popup',
                responsive: true,
                innerScroll: true,
                modalClass: 'config_quickview quickview-popup-wrapper',
                buttons: [{
                    text: $.mage.__('Close'),
                    class: 'modal-close',
                    click: function() {
                        this.closeModal();
                    }
                }]
            };
            setTimeout(() => {
                jQuery(document).find("#best-seller li.bestseller-section").each(function() {
                    $(this).click(function() {
                        $.cookie("item_list_id", "home_page_carousel_1");
                        $.cookie("item_list_name", "Home Page Carousel 1");
                    });
                })
            }, 1000);
            if ($('.best-sell-slider').length) {
                $('.best-sell-slider').not('.slick-initialized').slick({
                    dots: false,
                    infinite: false,
                    slidesToShow: 4,
                    slidesToScroll: 1,
                    arrows: true,
                    responsive: [{
                        breakpoint: 1200,
                        settings: {
                            slidesToShow: 4
                        },
                    }, {
                        breakpoint: 992,
                        settings: {
                            slidesToShow: 2
                        },
                    }, {
                        breakpoint: 640,
                        settings: {
                            dots: true,
                            slidesToShow: 2
                        },
                    }, ],
                });
            }
            setTimeout(() => {
                $("#best-seller li.bestseller-section").each(function() {
                    if ($(this).find(".product-item-actions #caddtowishlist").length != 0) {
                        $(this).find(".product-item-actions #caddtowishlist").unbind('click').on("click", function() {
                            var _self = $(this);
                            var proid = $(this).attr("productId");
                            $.ajax({
                                url: ajaxsuites_url,
                                method: 'get',
                                data: {
                                    productId: proid
                                },
                                dataType: 'json',
                                showLoader: true,
                                success: function(data) {
                                    var redirect = data.result.redirect;
                                    var isremove = data.result.isremove;
                                    if (redirect) {
                                        window.location.href = redirect_url;
                                    }
                                    if (isremove) {
                                        $(document).find("#wishlist_msg").remove();
                                        _self.removeClass("active_wishlist");
                                        $(document).find("#contentarea").after(`<p><div class="page messages" id="wishlist_msg"> <div data-placeholder="messages"></div> <div data-bind="scope: 'messages'"> <div aria-atomic="true" role="alert" class="messages"> <div class="message-success success message" data-ui-id="message-success"> <div>` + data.result.message + `</div> </div> </div> </div> </div></p>`);
                                        var dataLayer = window.dataLayer || [];
                                        var datalyerData = {
                                            event: 'remove_from_wishlist',
                                            ecommerce: data.result.productObj
                                        };
                                        dataLayer.push({
                                            ecommerce: null
                                        });
                                        dataLayer.push(datalyerData);
                                    } else {
                                        _self.addClass("active_wishlist");
                                        $(document).find("#wishlist_msg").remove();
                                        $(document).find("#wishlist_msg").remove();
                                        $(document).find("#contentarea").after(`<p><div class="page messages" id="wishlist_msg"> <div data-placeholder="messages"></div> <div data-bind="scope: 'messages'"> <div aria-atomic="true" role="alert" class="messages"> <div class="message-success success message" data-ui-id="message-success"> <div>` + data.result.prodName + ` Click <a href="` + location.origin + `">here</a> to continue shopping.</div> </div> </div> </div> </div></p>`);
                                        var dataLayer = window.dataLayer || [];
                                        var datalyerData = {
                                            event: 'add_to_wishlist',
                                            ecommerce: data.result.productObj
                                        };
                                        dataLayer.push({
                                            ecommerce: null
                                        });
                                        dataLayer.push(datalyerData);
                                    }
                                }
                            });
                        });
                    }
                });
            }, 2000);
            setTimeout(() => {
                $(document).find('#best-seller li.bestseller-section .config-pro-link').each(function() {
                    $(this).click(function() {
                        $(this).addClass('loading');
                        var prodUrl = $(this).attr('data-configurable-url');
                        var prodId = $(this).attr('data-product-id');
                        if (prodUrl.length) {
                            $(this).html('Add to cart');
                            $.ajax({
                                url: prodUrl,
                                data: {},
                                type: 'post',
                                showLoader: false,
                                dataType: 'json',
                                success: function(res) {
                                    $('.config-pro-link').removeClass('loading');
                                    if (res.content) {
                                        $("#config-modal-content .modal-inner-content").html(res.content);
                                        $("#config-modal-content").modal('openModal');
                                        $('body').trigger('contentUpdated');
                                    }
                                },
                                error: function(res) {
                                    $('.config-pro-link').removeClass('loading');
                                    alert('Error in sending ajax request');
                                }
                            });
                        }
                    });
                });
                modal(options, $('#config-modal-content'));
                $("#modal-btn").on('click', function() {
                    $("#config-modal-content").modal("openModal");
                });
            }, 1500);
        });
        var loginModalOpened = false;
        var grecaptchaRendered = false;
        var options = {
            type: 'popup',
            responsive: true,
            innerScroll: true,
            modalClass: "login_popup_form",
            buttons: [{
                text: $.mage.__('OK'),
                class: '',
                click: function() {
                    this.closeModal();
                }
            }],
            opened: function() {
                loginModalOpened = true;
            },
            closed: function() {
                loginModalOpened = false;
            }
        };
        $(document).off('click.wishlistLogin', '[id^="wishlist_login_popup1_"]').on('click.wishlistLogin', '[id^="wishlist_login_popup1_"]', function(e) {
            e.preventDefault();
            e.stopImmediatePropagation();
            if (loginModalOpened) {
                return false;
            }
            var $btn = $(this);
            var productId = $btn.attr('id').replace('wishlist_login_popup1_', '') || $btn.data('product-id');
            var customer = customerData.get('customer')();
            if (!customer || !customer.firstname) {
                $("#customer-popup-registration").hide();
                var element_render = 'tab-login-recaptcha';
                var validate = 'login-recaptcha';
                $('#login-recaptcha,#fogot-recaptcha,#create-recaptcha').val('');
                if (!grecaptchaRendered && $('#' + element_render).length) {
                    if (typeof grecaptcha !== 'undefined' && grecaptcha.render) {
                        grecaptcha.render(element_render, {
                            'sitekey': config.recaptchaSitekey,
                            'theme': "light",
                            'type': "image",
                            'size': "normal",
                            'callback': function(response) {
                                if (response && response.length > 0) {
                                    $('#' + validate).val('success');
                                    $('#double_send_otp_login').prop('disabled', false);
                                }
                            }
                        });
                        grecaptchaRendered = true;
                    }
                }
                modal(options, $('#login_overlay'));
                $('#login_overlay').modal('openModal');
                return false;
            }
        });
    };
});